function taskLabel(status){return ({open:'Mới',in_progress:'Đang làm',review:'Chờ Leader/Giám đốc duyệt',revision:'Cần sửa',done:'Hoàn thành',cancelled:'Đã hủy'})[status]||esc(status)}
function statusLabel(status){return ({pending:'Chờ duyệt',approved:'Đã duyệt',rejected:'Từ chối',ack:'Đã nhận',conflict:'Báo trùng lịch'})[status]||esc(status)}
function sortPersonalWork(tasks){return tasks.slice().sort((a,b)=>{const closed=t=>['done','cancelled','canceled'].includes(String(t.status)),ac=closed(a),bc=closed(b);if(ac!==bc)return ac?1:-1;if(ac)return (Date.parse(b.completed_at||b.created_at)||0)-(Date.parse(a.completed_at||a.created_at)||0);const ar=a.is_edit_task&&a.editor_received_at,br=b.is_edit_task&&b.editor_received_at;if(ar&&br)return Date.parse(ar)-Date.parse(br)||String(a.id).localeCompare(String(b.id));if(!!ar!==!!br)return ar?-1:1;return (Date.parse(b.created_at)||0)-(Date.parse(a.created_at)||0)})}
function workTaskCard(x){const closed=['done','cancelled','canceled'].includes(String(x.status)),overdue=!closed&&x.is_edit_task&&x.status!=='review'&&x.due_at&&Date.parse(x.due_at)<Date.now();let times=x.is_edit_task?(x.awaiting_assets?'Chờ bàn giao Raw/Voice — chưa bắt đầu tính 48 giờ.':'Nhận tư liệu lúc: '+fmt(x.editor_received_at)+'<br>Hạn nộp Video Final: '+fmt(x.due_at)):'Hạn '+fmt(x.due_at);const status=x.status==='review'?'Chờ duyệt':taskLabel(x.status);return '<div class="item"'+(overdue?' style="border-left:4px solid #ff918b;padding-left:12px"':'')+'><div class="row"><b>'+esc(x.title)+'</b><span class="badge">'+esc(status)+'</span></div><small>'+esc(x.category)+' · SL '+esc(x.quantity)+' · Trọng số '+esc(x.weight)+'</small><small'+(overdue?' style="color:#ff918b"':'')+'>'+times+(overdue?' · Quá hạn':'')+'</small>'+(x.production_id?(x.is_vj_task?vjScriptMarkup(x.production_item||{}):x.is_edit_task?editorProgressMarkup(x.production_item||{}):'')+'<button type="button" data-open-production-work="'+esc(x.production_id)+'">Xem task</button>':state.user.role!=='director'&&String(x.assignee_id)===String(state.user.id)&&['open','in_progress','revision'].includes(x.status)?'<button data-submit="'+esc(x.id)+'">Gửi hoàn thành</button>':'')+'</div>'}
function workListSection(tasks,title,team){const closed=t=>['done','cancelled','canceled'].includes(String(t.status)),open=tasks.filter(t=>!closed(t)),archive=tasks.filter(closed);return '<section class="card"><h2>'+title+'</h2>'+((open.length?open.map(workTaskCard).join(''):'<div class="empty">Chưa có công việc đang làm.</div>'))+'</section>'+(archive.length?'<section class="card"><details><summary>Đã hoàn thành / Đã hủy ('+archive.length+')</summary>'+archive.map(workTaskCard).join('')+'</details></section>':'')}
