 const t=sortPersonalWork((state.tasks||[]).filter(x=>String(x.assignee_id)===String(state.user.id))),manager=false,q=state.reviewQueue,team=false;
 $('screen').innerHTML=`${manager?'<div class="chips"><button id="myWork" class="chip '+(!team?'on':'')+'">Việc của tôi</button><button id="teamWork" class="chip '+(team?'on':'')+'">Việc của team</button></div>':''}${`<section class="card"><h2>${team?'Việc cần xử lý của team':'Việc cần tôi xử lý'}</h2>${!Array.isArray(q)?'<div class="muted">Đang tải danh sách chờ duyệt…</div>':q.length?q.map(x=>x.operational_kind?operationalWorkCard(x):x.production_id?`<div class="item"><b>${esc(x.title)}</b><small>${esc(x.project)} · ${esc(({idea:'Duyệt Idea',content:'Duyệt Final Content',media:'Duyệt Final Media',vj:'VJ chính duyệt Final'})[x.kind])}</small><small>Người tạo: ${esc(x.assignee_name)}</small><button type="button" data-open-work-approval="${esc(x.production_id)}" data-kind="${esc(x.kind)}">${state.user.role==='director'?'Xem task':'Mở để duyệt'}</button></div>`:`<div class="item"><b>${esc(x.title)}</b><small>${esc(x.assignee_name)} · Hạn ${fmt(x.due_at)}</small>${state.user.role!=='director'?`<div class="actions"><button data-review-queue="${esc(x.id)}" data-decision="done">Duyệt hoàn thành</button><button class="danger" data-review-queue="${esc(x.id)}" data-decision="revision">Yêu cầu sửa</button></div>`:''}</div>`).join(''):'<div class="empty">Không có việc nào chờ duyệt.</div>'}</section>`}${workListSection(team?state.allTasks||[]:t,team?'Việc của team':'Việc của tôi',team)}`;
 if($('myWork'))$('myWork').onclick=()=>{window._tasksScope='personal';state.reviewQueue=null;render();loadReviewQueue()};if($('teamWork'))$('teamWork').onclick=async()=>{window._tasksScope='team';state.reviewQueue=null;render();await loadManagerData();loadReviewQueue()};
