   let items=(cfg.multi?cfg.inputs.map(x=>({id:String(x.value),text:x.closest('label')?.textContent||''})):Array.from(cfg.select.options).filter(x=>x.value).map(x=>({id:String(x.value),text:x.textContent}))).map(x=>{const p=records.get(x.id)||{telegram_id:x.id,name:x.text};return {...x,p,name:compactPickerName(p),workRole:cfg.role==='thumbnail'?(p.production_roles?.includes('editor')?'editor':'designer'):['content','media','approver'].includes(cfg.role)?'leader':cfg.role}});
