   const previousOverflow=document.body.style.overflow,protectedNodes=[document.getElementById('app'),document.querySelector('header')].filter(Boolean).map(node=>({node,inert:node.inert}));protectedNodes.forEach(x=>x.node.inert=true);document.body.style.overflow='hidden';compactPeoplePickerOpen=true;document.body.append(overlay);
   const dismiss=()=>{overlay.remove();document.body.style.overflow=previousOverflow;protectedNodes.forEach(x=>x.node.inert=x.inert);compactPeoplePickerOpen=false;compactPeoplePickerDismiss=null;document.removeEventListener('keydown',keyHandler);if(trigger.isConnected)trigger.focus();};
