 const filter=window._v19Filter||'all',day=window._v19Day||'',dateType=window._v19DateType||'all',approvalKey=['script_approval','final_approval'].includes(window._v19ApprovalKey)?'':window._v19ApprovalKey||'',approvalStatus=window._v19ApprovalStatus||'',list=all,st=current?(state.productionPage?.stats?(state.productionPage.stats[current]||statsFor([])):statsFor(all.filter(x=>String(x.project||'').trim()===current))):Object.values(state.productionPage?.stats||{}).reduce((sum,row)=>{for(const key of ['total','shooting','waiting','edited','published'])sum[key]+=Number(row[key]||0);return sum},{total:0,shooting:0,waiting:0,edited:0,published:0});
