 $('screen').innerHTML=(approvalFocus?'<section class="card"><h2>'+(approvalFocus.kind==='idea'?'Duyệt Idea':approvalFocus.kind==='task'?'Nội dung sản xuất':'Video Final')+'</h2><p>'+(approvalFocus.stale?'Thông báo thuộc lượt cũ. Dưới đây là phiên bản hiện tại của task.':'Bạn đang xem đúng task từ thông báo Telegram.')+'</p><button type="button" id="exitApprovalFocus" class="secondary">Xem tất cả sản xuất</button></section><div hidden>'+productionHeader+'</div></div><div id="approvalFocusedResults">':productionHeader)+(productionCards||'<section class="card empty">Chưa có nội dung phù hợp.</section>')+(approvalFocus?'':productionMore)+'</div>';if($('exitApprovalFocus'))$('exitApprovalFocus').onclick=()=>go('production');
