const rememberKey='viral-remembered-device';
let usingRememberedSession=false;
function loadRememberedSession(){try{return localStorage.getItem(rememberKey)||'';}catch(e){return '';}}
function clearRememberedSession(){try{localStorage.removeItem(rememberKey);}catch(e){}usingRememberedSession=false;}
async function persistRememberedSession(){
 try{
  const result=await call('rememberDevice',loadRememberedSession());
  if(!/^v4\.\d+\.[a-f0-9]{32}\.[a-f0-9]{64}$/.test(result?.token||''))return;
  localStorage.setItem(rememberKey,result.token);
 }catch(e){console.warn('Không lưu được phiên trên thiết bị này.');}
}
async function logoutRememberedDevice(){
 if(!confirm('Đăng xuất và bỏ ghi nhớ trên thiết bị này?'))return;
 const token=loadRememberedSession();
 try{if(token)await call('forgetDevice',token);}catch(e){alert('Không thu hồi được phiên trên máy chủ. Thử lại khi có kết nối: '+(e.message||String(e)));return;}
 clearRememberedSession();forgetMainLogin();clearTimeout(mainLoginTimer);mainLoginRequest=null;state=null;init='';$('nav').innerHTML='';showMainLogin();
}

window.__viralBootStarted = true;

function signedSession(value) {
 const raw=String(value||'').trim();
 if(/^v2\.\d+\.[a-f0-9]{64}$/.test(raw)||/^v1\.\d+\.\d+\.[a-f0-9]{64}$/.test(raw)||/^v3\.\d+\.\d+\.[a-f0-9]{32}\.[a-f0-9]{64}$/.test(raw))return raw;
 let data=raw;
 for(let n=0;n<3&&data;n++){
  const p=new URLSearchParams(data.replace(/^[#?]/,'')),nested=p.get('tgWebAppData');
  if(nested){data=nested;continue;}
  if(/^[a-f0-9]{64}$/i.test(p.get('hash')||''))return data;
  try{const next=decodeURIComponent(data);if(next===data)break;data=next;}catch(e){break;}
 }
 return '';
}
function publicRpc(method,...args){
 return new Promise((resolve,reject)=>{
  let done=false;const timer=setTimeout(()=>finish(Error('Chưa kết nối được Apps Script. Đóng rồi mở lại ứng dụng, hoặc dùng nút mở trong tin nhắn bot.')),30000);
  function finish(error,value){if(done)return;done=true;clearTimeout(timer);error?reject(error):resolve(value);}
  try{google.script.run.withSuccessHandler(v=>finish(null,v)).withFailureHandler(e=>finish(Error(e.message||String(e))))[method](...args);}catch(e){finish(e);}
 });
}
let bootAttempt=0,mainLoginRequest=null,mainLoginTimer=null,mainLoginChecking=false;
