async function hrList(){formDirty=true;hrBusy();try{hrDirectory=await call('personnelDirectory');$('screen').innerHTML='<section class="card"><h2>Hồ sơ nhân sự</h2><button id="hrBack" class="secondary">Quay lại</button><button id="hrAdd">+ Thêm nhân viên</button><label>Tìm tên / mã nhân viên / Telegram ID<input id="hrSearch" placeholder="Nhập từ khóa"></label><label>Trạng thái<select id="hrStatus"><option value="all">Tất cả</option><option value="active">Đang làm</option><option value="inactive">Đã ngừng hoạt động</option></select></label></section><section class="card"><details><summary>Thông tin cần bổ sung ('+hrDirectory.issues.length+')</summary>'+hrDirectory.issues.map(x=>'<p>'+esc(x)+'</p>').join('')+'</details></section><div id="hrPeople"></div>';$('hrBack').onclick=hrBack;$('hrAdd').onclick=()=>hrEdit({active:true,role:'employee',revision:0});$('hrSearch').oninput=hrDrawList;$('hrStatus').onchange=hrDrawList;hrDrawList()}catch(e){hrError(e)}}
function hrDrawList(){const q=$('hrSearch').value.trim().toLowerCase(),status=$('hrStatus').value;const people=hrDirectory.people.filter(p=>(status==='all'||p.active===(status==='active'))&&[p.name,p.employee_code,p.telegram_id,p.department].join(' ').toLowerCase().includes(q));$('hrPeople').innerHTML=people.map((p,i)=>'<section class="card"><b>'+esc(p.display_name)+'</b><p>'+esc(p.department)+' · '+esc(p.job_title||'Chưa có chức vụ')+' · '+(p.active?'Đang làm':'Ngừng hoạt động')+'</p><small>Telegram ID: '+esc(p.telegram_id)+'</small><div class="actions"><button data-hr-edit="'+i+'">Sửa thông tin</button><button class="secondary" data-hr-bank="'+i+'">Ngân hàng</button></div></section>').join('')||'<section class="card">Không tìm thấy nhân viên.</section>';$('hrPeople').querySelectorAll('[data-hr-edit]').forEach(b=>b.onclick=()=>hrEdit(people[Number(b.dataset.hrEdit)]));$('hrPeople').querySelectorAll('[data-hr-bank]').forEach(b=>b.onclick=()=>hrBank(people[Number(b.dataset.hrBank)].employee_id))}
function hrEdit(p){formDirty=true;const director=hrDirectory?.director===true,field=(name,label,type='text',required=false)=>'<label>'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(p[name]||'')+'" '+(required?'required':'')+' maxlength="100"></label>';$('screen').innerHTML='<section class="card"><h2>'+(p.employee_id?'Sửa hồ sơ':'Thêm nhân viên')+'</h2><p>Mã nhân viên do kế toán cấp. Tên có thể trùng; mã và Telegram ID phải riêng.</p><form id="hrEditForm">'+field('name','Họ tên','text',true)+field('employee_code','Mã nhân viên','text',true)+field('telegram_id','Telegram ID','text',true)+field('department','Phòng ban','text',true)+field('job_title','Chức vụ')+'<label>Quyền sử dụng<select name="role" '+(!director?'disabled':'')+'>'+[['employee','Nhân viên'],['leader','Leader'],['director','Giám đốc']].map(([value,label])=>'<option value="'+value+'" '+(p.role===value?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label>Trạng thái<select name="active"><option value="true" '+(p.active?'selected':'')+'>Đang hoạt động</option><option value="false" '+(!p.active?'selected':'')+'>Ngừng hoạt động</option></select></label>'+field('joined_on','Ngày vào làm','date')+field('left_on','Ngày nghỉ việc','date')+'<button type="submit">Lưu thông tin</button></form><button id="hrCancel" class="secondary">Quay lại danh sách</button>'+(p.employee_id?'<button id="hrHistory" class="secondary">Lịch sử sửa / khôi phục</button>':'')+'</section>';$('hrCancel').onclick=()=>hrList();if(p.employee_id&&(state.user.role==='director'||String(state.user.id)===String(p.telegram_id)||state.user.role==='leader'&&state.user.department===p.department))hrAddEntry('employeePerformance','Xem hiệu suất',()=>{if($('hrEditForm')?.dataset.edited&&!confirm('Bạn có thay đổi chưa lưu. Chuyển sang hiệu suất?'))return;openPerformance(p.telegram_id)});$('hrEditForm').oninput=()=>{$('hrEditForm').dataset.edited='true'};$('hrEditForm').onchange=()=>{$('hrEditForm').dataset.edited='true'};if($('hrHistory'))$('hrHistory').onclick=()=>hrHistory(p);$('hrEditForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const f=e.target,data=Object.fromEntries(['name','employee_code','telegram_id','department','job_title','role','active','joined_on','left_on'].map(k=>[k,f.elements.namedItem(k).value]));data.employee_id=p.employee_id||'';data.revision=p.revision;data.active=data.active==='true';if(p.employee_id&&data.telegram_id.trim()!==p.telegram_id){if(!confirm('Đổi Telegram ID sẽ chuyển liên kết lịch sử sang ID mới và thu hồi ghi nhớ của ID cũ. Bạn chắc chắn ID mới đúng người?'))return;data.confirm_identity_change=true}if(p.employee_id&&(data.role!==p.role||data.active!==p.active)&&!confirm('Xác nhận thay đổi quyền / trạng thái hoạt động?'))return;busy=true;f.querySelector('[type="submit"]').disabled=true;try{const r=await call('savePersonnel',data);hrInvalidate();if(r.selfChanged){clearRememberedSession();init='';formDirty=false;await showMainLogin();msg('Đã đổi Telegram ID. Dùng tài khoản Telegram mới để xác nhận.');return}if(r.selfAccessChanged){formDirty=false;if(!r.employee.active){clearRememberedSession();init='';await showMainLogin()}else startApp();return}msg(r.warning||'Đã lưu hồ sơ nhân viên.');await hrList()}catch(e){hrError(e);f.querySelector('[type="submit"]').disabled=false}finally{busy=false}}}
function hrInvalidate(){coreReady=false;corePromise=null;productionReady=false;lastManagerRefresh=0;productionPageCache.clear();pendingReadCalls.clear();workloadAt=0}
async function hrHistory(p,offset=0){hrBusy('Đang tải lịch sử…');try{const r=await call('personnelHistory',p.employee_id,offset);$('screen').innerHTML='<section class="card"><h2>Lịch sử · '+esc(p.display_name)+'</h2><button id="hrHistoryBack" class="secondary">Quay lại hồ sơ</button></section>'+r.items.map((x,i)=>'<section class="card"><b>'+esc(x.at)+'</b><small>Người sửa: '+esc(x.actor_id)+'</small><p>Trước: '+esc(JSON.stringify(x.before))+'</p><p>Sau: '+esc(JSON.stringify(x.after))+'</p>'+(x.before.telegram_id?'<button data-hr-restore="'+i+'">Khôi phục thông tin trước lần sửa này</button>':'')+'</section>').join('')+(r.hasMore?'<button id="hrHistoryMore">Xem các lần cũ hơn</button>':'');$('hrHistoryBack').onclick=()=>hrEdit(p);if($('hrHistoryMore'))$('hrHistoryMore').onclick=()=>hrHistory(p,offset+20);$('screen').querySelectorAll('[data-hr-restore]').forEach(b=>b.onclick=async()=>{if(busy||!confirm('Khôi phục thông tin cũ? Việc khôi phục được ghi thành một lần sửa mới; thay đổi Telegram ID sẽ chuyển liên kết lịch sử.'))return;busy=true;b.disabled=true;try{const result=await call('restorePersonnel',p.employee_id,r.items[Number(b.dataset.hrRestore)].id,p.revision);hrInvalidate();if(result.selfChanged){clearRememberedSession();init='';await showMainLogin()}else await hrList();msg('Đã khôi phục hồ sơ.')}catch(e){hrError(e);b.disabled=false}finally{busy=false}})}catch(e){hrError(e)}}
async function hrBank(key){formDirty=true;hrBusy('Đang tải thông tin ngân hàng…');try{const r=await call('bankProfile',key||''),p=r.employee,b=r.bank,current=b.account_number?{bank_name:b.bank_name,account_number:b.account_number,holder_name:b.holder_name}:null,draft=b.pending||current||{};const info=v=>v?'<p>Ngân hàng: '+esc(v.bank_name)+'<br>Số tài khoản: '+esc(v.account_number)+'<br>Chủ tài khoản: '+esc(v.holder_name)+'</p>':'<p>Chưa có tài khoản đã duyệt.</p>';$('screen').innerHTML='<section class="card"><h2>Ngân hàng · '+esc(p.display_name)+'</h2><button id="bankBack" class="secondary">Quay lại</button><h3>Thông tin đã duyệt</h3>'+info(current)+(b.pending?'<h3>Thông tin đang chờ duyệt</h3>'+info(b.pending)+(r.manager?'<button id="bankApprove">Duyệt thay đổi</button><button id="bankReject" class="secondary">Từ chối</button>':'<p>Kế toán hoặc giám đốc sẽ kiểm tra yêu cầu.</p>'):'')+'<h3>Đề nghị cập nhật</h3><form id="bankForm"><label>Ngân hàng<input name="bank_name" maxlength="100" required value="'+esc(draft.bank_name||'')+'" list="banks"></label><datalist id="banks">'+['Vietcombank','BIDV','VietinBank','Agribank','MB Bank','Techcombank','ACB','VPBank','TPBank','Sacombank','HDBank','VIB','SHB'].map(x=>'<option value="'+x+'">').join('')+'</datalist><label>Số tài khoản<input name="account_number" type="text" inputmode="numeric" pattern="[0-9 ]{6,30}" required value="'+esc(draft.account_number||'')+'"></label><label>Tên chủ tài khoản<input name="holder_name" maxlength="100" required value="'+esc(draft.holder_name||'')+'"></label><p class="muted">Thay đổi chỉ có hiệu lực sau khi được duyệt. Số 0 đầu tài khoản được giữ nguyên.</p><button type="submit">Gửi đề nghị cập nhật</button></form></section>';$('bankBack').onclick=()=>r.manager&&key?hrList():hrBack();const action=async(method,...args)=>{if(busy)return;busy=true;try{await call(method,...args);await hrBank(p.employee_id);msg('Đã cập nhật thông tin ngân hàng.')}catch(e){hrError(e)}finally{busy=false}};$('bankForm').onsubmit=e=>{e.preventDefault();const f=e.target;action('proposeBankProfile',p.employee_id,Object.fromEntries(['bank_name','account_number','holder_name'].map(k=>[k,f.elements.namedItem(k).value])),b.revision)};if($('bankApprove'))$('bankApprove').onclick=()=>{if(confirm('Đã kiểm tra ngân hàng, số tài khoản và chủ tài khoản?'))action('reviewBankProfile',p.employee_id,'approve',b.revision)};if($('bankReject'))$('bankReject').onclick=()=>action('reviewBankProfile',p.employee_id,'reject',b.revision)}catch(e){hrError(e)}}


// V20.19.1: immediate selection feedback without waiting for the server.
function paintProjectMetricSelection(key){
 $('screen').querySelectorAll('[data-project-metric]').forEach(b=>{const selected=b.dataset.projectMetric===key;b.classList.toggle('on',selected);b.setAttribute('aria-pressed',String(selected))});
 $('screen').querySelectorAll('[data-prod-filter]').forEach(b=>b.classList.toggle('on',b.dataset.prodFilter==='all'));
 for(const id of ['productionSearch','productionDay','productionApprovalKey','productionApprovalStatus']){const input=$(id);if(input)input.value=''}
}
// V20.19: shared performance screen, fetched only when opened.
let performanceRequest=0;
function openPerformance(id){window._performancePerson=String(id||'');go('performance')}
async function performanceView(){
 const request=++performanceRequest,month=window._performanceMonth||String(state.today||'').slice(0,7),person=window._performancePerson||'',mode=window._performanceMode||'month',period={mode,month,day:window._performanceDay||state.today,from:window._performanceFrom||state.today,to:window._performanceTo||state.today};
 $('screen').innerHTML='<section class="card empty">Đợi xíu nha…<p>Bot đang chạy deadline cùng bạn.</p></section>';
 try{const r=await call('personnelPerformance',period,person);if(tab!=='performance'||request!==performanceRequest)return;
 const labels={idea:'Idea đã duyệt',shoot:'Đã bàn giao tư liệu',edit:'Video đã hoàn thành'};
 $('screen').innerHTML='<section class="card"><h2>Hiệu suất sản xuất</h2><label>Chế độ xem<select id="performanceMode">'+[['month','Theo tháng'],['day','Theo ngày'],['range','Khoảng ngày']].map(([key,label])=>'<option value="'+key+'" '+(mode===key?'selected':'')+'>'+label+'</option>').join('')+'</select></label><div class="grid"><label '+(mode==='month'?'':'hidden')+'>Tháng<input id="performanceMonth" type="month" value="'+esc(r.month)+'"></label><label '+(mode==='day'?'':'hidden')+'>Ngày<input id="performanceDay" type="date" value="'+esc(period.day)+'"></label><label '+(mode==='range'?'':'hidden')+'>Từ ngày<input id="performanceFrom" type="date" value="'+esc(period.from)+'"></label><label '+(mode==='range'?'':'hidden')+'>Đến ngày<input id="performanceTo" type="date" value="'+esc(period.to)+'"></label><label>Nhân viên<select id="performancePerson"><option value="">'+(r.scope==='self'?'Tôi':r.scope==='team'?'Team của tôi':'Toàn công ty')+'</option>'+r.people.map(p=>'<option value="'+esc(p.id)+'" '+(p.id===person?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label></div>'+(mode==='range'?'<button type="button" id="performanceRangeApply">Áp dụng khoảng ngày</button>':'')+'<p>'+esc(r.notice)+'</p><p><b>'+r.approvedVideos+'</b> video đã hoàn thành trong phạm vi đang xem (mỗi video tính một lần).</p><small>Dữ liệu được ghi từ khi bật V20.19. '+r.untracked+' nội dung cũ thiếu mốc trong phạm vi đang xem chưa được tính đủ; không dùng số liệu này để chấm điểm tự động.</small><button id="performanceBack" class="secondary">Về Tiện ích</button></section><div id="performancePeople">'+r.results.map((p,i)=>'<section class="card"><h2>'+esc(p.name)+'</h2><small>'+esc(p.department)+'</small><div class="stats">'+Object.entries(labels).map(([key,label])=>'<button class="stat secondary" data-performance-person="'+i+'" data-performance-kind="'+key+'"><b>'+p.counts[key]+'</b><small>'+label+'</small></button>').join('')+'</div><p>Đang làm: '+p.inProgress+' · Quá hạn: '+p.overdue+' (hiện tại)</p><p>Đúng hạn: '+p.onTime+'/'+p.withDeadline+' mốc có deadline'+(p.withDeadline?' · '+Math.round(100*p.onTime/p.withDeadline)+'%':'')+'</p><div id="performanceDetails'+i+'"></div></section>').join('')+'</div>';
 $('performanceMode').onchange=e=>{window._performanceMode=e.target.value;performanceView()};$('performanceDay').onchange=e=>{window._performanceDay=e.target.value;performanceView()};if($('performanceRangeApply'))$('performanceRangeApply').onclick=()=>{const from=$('performanceFrom').value,to=$('performanceTo').value;if(!from||!to||from>to){msg('Chọn đủ khoảng ngày hợp lệ',true);return}window._performanceFrom=from;window._performanceTo=to;performanceView()};$('performanceMonth').onchange=e=>{window._performanceMonth=e.target.value;performanceView()};$('performancePerson').onchange=e=>{window._performancePerson=e.target.value;performanceView()};$('performanceBack').onclick=()=>go('utilities');
 $('screen').querySelectorAll('[data-performance-kind]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.performancePerson),kind=b.dataset.performanceKind,items=r.results[i].items.filter(x=>x.kind===kind).sort((a,b)=>String(b.at).localeCompare(String(a.at))),slot=$('performanceDetails'+i);let limit=20;const draw=()=>{slot.innerHTML='<h3>'+esc(labels[kind])+'</h3>'+items.slice(0,limit).map(x=>'<div class="item"><b>'+esc(x.title)+'</b><small>'+esc(x.project)+' · '+fmt(x.at)+'</small></div>').join('')+(items.length?'<small>'+Math.min(limit,items.length)+'/'+items.length+' nội dung</small>':'<p>Chưa có mốc hoàn thành trong khoảng đang xem.</p>')+(items.length>limit?'<button class="secondary" data-performance-more>Xem thêm</button>':'');const more=slot.querySelector('[data-performance-more]');if(more)more.onclick=()=>{limit+=20;draw()}};draw()});
 }catch(e){if(tab!=='performance'||request!==performanceRequest)return;$('screen').innerHTML='<section class="card"><p>'+esc(e.message||String(e))+'</p><button id="performanceRetry">Thử lại</button><button id="performanceBack" class="secondary">Về Tiện ích</button></section>';$('performanceRetry').onclick=()=>performanceView();$('performanceBack').onclick=()=>go('utilities')}
}
async function bindLoanProjectFields(form){
 const project=form.elements.project,production=form.elements.production_id;let version=0,items=[];const submit=form.querySelector('button');if(submit)submit.disabled=true;
 const valid=()=>tab==='equipment'&&$('loanForm')===form;
 const reset=()=>{items=[];production.innerHTML='<option value="">Không liên kết nội dung</option>';production.value='';production.disabled=false};
 project.onchange=async()=>{const request=++version;reset();if(!project.value||project.value==='Công việc nội bộ')return;production.disabled=true;try{const r=await call('equipmentProjectOptions',project.value);if(!valid()||request!==version)return;items=r.items;production.innerHTML='<option value="">Không liên kết nội dung</option>'+items.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.title)+'</option>').join('')}catch(e){if(valid()&&request===version)msg(e.message||String(e),true)}finally{if(valid()&&request===version)production.disabled=false}};
 production.onchange=()=>{const item=items.find(x=>x.id===production.value),borrow=form.elements.borrow_at;if(item?.shoot_at&&!borrow.value){const d=new Date(item.shoot_at);if(!isNaN(d)){borrow.value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}}};
 try{const r=await call('equipmentProjectOptions','');if(!valid())return;project.innerHTML='<option value="">Chọn dự án</option><option value="Công việc nội bộ">Công việc nội bộ</option>'+r.projects.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('');if(submit)submit.disabled=false}catch(e){if(valid()){msg(e.message||String(e),true);project.innerHTML='<option value="">Không tải được dự án — hãy làm mới</option>'}}
}

// ===== V20.20: attendance on location =====
function fieldStatusLabel(status){return {approved:'Đã xác nhận',pending:'Chờ xác nhận',needs_info:'Cần bổ sung'}[status]||'Đã ghi nhận'}
function fieldPointMarkup(a,kind,names={},review=false){
 const time=kind==='in'?a?.check_in:a?.check_out;if(!time)return '';const p=a[kind+'_context'],label=kind==='in'?'Vào ca':'Xuống ca';if(!p)return '<div class="item"><b>'+label+': '+fmt(time)+'</b><small>Văn phòng · Bản ghi cũ</small></div>';
 const mapUrl='https:'+String.fromCharCode(47,47)+'www.google.com/maps?q='+p.lat+','+p.lng;
 const map=Number.isFinite(p.lat)&&Number.isFinite(p.lng)?'<a target="_blank" rel="noopener noreferrer" href="'+esc(mapUrl)+'">Xem vị trí GPS</a>':'Không có GPS';
 return '<div class="item"><div class="row"><b>'+label+' · '+fmt(time)+'</b><span class="badge '+(p.status!=='approved'?'wait':'')+'">'+fieldStatusLabel(p.status)+'</span></div><small>'+(p.mode==='shoot'?'Đi quay':'Văn phòng')+' · '+esc(p.place)+'</small>'+(p.project?'<small>'+esc(p.project)+(p.production_title?' · '+esc(p.production_title):'')+'</small>':'')+'<small>'+map+(p.accuracy!==null?' · Sai số '+Math.round(p.accuracy)+'m':'')+'</small>'+(p.reason?'<small>Lý do: '+esc(p.reason)+'</small>':'')+(p.feedback?'<small>Phản hồi: '+esc(p.feedback)+'</small>':'')+(p.reviewed_by?'<small>Xác nhận: '+esc(p.reviewed_by==='system'?'Tự động theo điều kiện chấm công':names[p.reviewed_by]||state.peopleNames?.[p.reviewed_by]||p.reviewed_by)+' · '+fmt(p.reviewed_at)+'</small>':'')+'<details><summary>Lịch sử</summary>'+(p.history||[]).map(x=>'<p><small>'+fmt(x.at)+' · '+esc(names[x.actor]||state.peopleNames?.[x.actor]||x.actor)+' · '+esc({submit:'Ghi nhận',review:'Xác nhận / yêu cầu bổ sung',supplement:'Bổ sung thông tin'}[x.action]||x.action)+(x.note?' · '+esc(x.note):'')+'</small></p>').join('')+'</details>'+(!review&&p.mode==='shoot'&&p.status!=='approved'?'<button type="button" class="secondary" data-field-supplement="'+kind+'">Bổ sung thông tin</button>':'')+'</div>';
}
function fieldControlsMarkup(){
 const a=state.attendance;if(a?.check_out)return '';const kind=a?'out':'in',last=a?.in_context,mode=last?.mode||'office';
 return '<form id="fieldClockForm" data-kind="'+kind+'"><label>Địa điểm '+(kind==='in'?'vào ca':'xuống ca')+'<select name="mode"><option value="office" '+(mode==='office'?'selected':'')+'>Văn phòng</option><option value="shoot" '+(mode==='shoot'?'selected':'')+'>Đi quay</option></select></label><p id="fieldOfficeHint" class="muted">Văn phòng: cần GPS chính xác và trong phạm vi quy định.</p><div id="fieldShootFields" '+(mode==='office'?'hidden':'')+'><label>Dự án<select name="project"><option value="">Chọn dự án</option></select></label><label>Video / lịch quay<select name="production_id"><option value="">Quay đột xuất / chưa có lịch</option></select></label><label>Địa điểm quay<input name="place" maxlength="200" value="'+esc(last?.mode==='shoot'?last.place:'')+'" placeholder="Ví dụ: Chợ Cồn"></label><label>Lý do / ghi chú<textarea name="reason" maxlength="1000" rows="2" placeholder="Bắt buộc nếu ngoài lịch hoặc không có GPS"></textarea></label><label class="team-picker"><input name="no_gps" type="checkbox"> Không lấy được GPS — gửi để người phụ trách xác nhận</label><small id="fieldScheduleHint">Đúng lịch quay hôm nay và GPS ≤100m được ghi nhận trực tiếp.</small></div><p id="fieldGPSHint" class="muted"></p><button id="fieldClockSubmit" type="submit">'+(kind==='in'?'● Vào ca':'↪ Xuống ca')+'</button></form>';
}
