let financeState={period:'',project:'all',report:null,error:'',loading:false,request:0,loadedAt:0};
function financeMoney(v){return Number(v||0).toLocaleString('vi-VN',{maximumFractionDigits:2})+' đ'}
function financeView(){
 if(state.user.role!=='director'){$('screen').innerHTML='<section class="card">Bạn không có quyền xem Thu chi.</section>';return}
 if(!financeState.period)financeState.period=String(state.today).slice(0,7);
 if(!$('financePeriod'))drawFinance();if(!financeState.report&&!financeState.loading&&!financeState.error)loadFinance();
}
function drawFinance(){
 if(tab!=='finance')return;const s=financeState,r=s.report,periods=[...new Set([s.period,...(r?.periods||[])])],label=p=>p.length===4?'Cả năm '+p:'Tháng '+p.slice(5)+' / '+p.slice(0,4);
 const tile=g=>`<button type="button" class="card finance-tile ${s.project===g.key?'selected':''}" data-finance-project="${esc(g.key)}" aria-pressed="${s.project===g.key}"><div class="row"><b>${esc(g.name)}</b><span>›</span></div><div class="finance-pair"><div><small>Thu</small><b class="finance-income">${financeMoney(g.income)}</b></div><div><small>Chi</small><b>${financeMoney(g.expense)}</b></div></div><small>Chênh lệch ${financeMoney(g.balance)} · ${g.count} giao dịch</small></button>`;
 $('screen').innerHTML=`<section class="card"><div class="row"><label>Thời gian báo cáo<select id="financePeriod">${periods.map(p=>`<option value="${esc(p)}" ${p===s.period?'selected':''}>${esc(label(p))}</option>`).join('')}</select></label><button id="financeRefresh" class="secondary" ${s.loading?'disabled':''}>${s.loading?'Đang tải…':'↻ Làm mới'}</button></div><label>Chọn tháng khác<input id="financeMonth" type="month" value="${esc(s.period.length===7?s.period:'')}" /></label><small>${r?'Đọc lúc '+new Date(r.readAt).toLocaleString('vi-VN'):'Dữ liệu từ Sheet thu chi'}</small></section>${s.error?`<section class="card"><p role="alert">${esc(s.error)}</p></section>`:''}${r?`<h2>Tổng công ty</h2><div class="finance-summary"><section class="card"><small>Tổng thu</small><b class="finance-income">${financeMoney(r.total.income)}</b></section><section class="card"><small>Tổng chi</small><b>${financeMoney(r.total.expense)}</b></section><section class="card finance-balance"><small>Chênh lệch thu–chi</small><b>${financeMoney(r.total.balance)}</b></section></div>${r.issueCount?`<section class="card"><b>Cần kiểm tra ${r.issueCount} dòng trong Sheet</b><p>Những dòng này chưa tính vào báo cáo.</p>${r.issues.map(x=>`<small>Dòng ${x.row}: ${esc(x.message)}</small>`).join('')}</section>`:''}<h2>Chung công ty</h2>${r.groups.filter(g=>['common','unclassified'].includes(g.key)).map(tile).join('')}<h2>Theo dự án / bộ phận</h2>${r.groups.filter(g=>!['common','unclassified'].includes(g.key)).map(tile).join('')||'<section class="card empty">Chưa có dự án.</section>'}<section class="card" id="financeDetail"><div class="row"><h3>${esc(s.project==='all'?'Tất cả giao dịch':r.groups.find(g=>g.key===s.project)?.name||'Giao dịch')}</h3>${s.project!=='all'?'<button class="secondary compact" id="financeAll">Xem tất cả</button>':''}</div><small>${r.count} giao dịch · ${esc(label(r.period))}</small>${r.items.map(x=>`<details class="item"><summary class="finance-transaction"><span>${esc(x.title||'Chưa ghi nội dung')}<small>${esc(x.date.split('-').reverse().join('/'))} · ${esc(x.id)}</small></span><b class="${x.type==='THU'?'finance-income':''}">${x.type==='THU'?'+':'−'}${financeMoney(x.amount)}</b></summary><p>Nhóm: ${esc(x.group||'Chưa ghi')}<br>Dự án: ${esc(x.project||'Chưa phân loại')}<br>Người thực hiện: ${esc(x.person||'Chưa ghi')}<br>Phương thức: ${esc(x.method||'Chưa ghi')}</p><div class="actions">${x.billLinks.map((url,i)=>`<a class="secondary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Mở bill${x.billLinks.length>1?' '+(i+1):''}</a>`).join('')}${x.invoiceLinks.map((url,i)=>`<a class="secondary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Mở hóa đơn${x.invoiceLinks.length>1?' '+(i+1):''}</a>`).join('')}</div>${!x.billLinks.length&&!x.invoiceLinks.length?'<small>Chưa có link chứng từ</small>':''}</details>`).join('')||'<p>Chưa có giao dịch trong thời gian này.</p>'}${r.nextOffset!==null?`<button id="financeMore" class="secondary" ${s.loading?'disabled':''}>Xem thêm giao dịch</button>`:''}</section>`:s.loading?'<section class="card empty">Đang tải báo cáo thu chi…</section>':''}`;
 $('financePeriod').onchange=e=>{s.period=e.target.value;s.project='all';s.report=null;loadFinance()};$('financeMonth').onchange=e=>{if(e.target.value){s.period=e.target.value;s.project='all';s.report=null;loadFinance()}};$('financeRefresh').onclick=()=>loadFinance();
 $('screen').querySelectorAll('[data-finance-project]').forEach(b=>b.onclick=()=>{s.project=s.project===b.dataset.financeProject?'all':b.dataset.financeProject;loadFinance()});if($('financeAll'))$('financeAll').onclick=()=>{s.project='all';loadFinance()};if($('financeMore'))$('financeMore').onclick=()=>loadFinance(true);
}
async function loadFinance(more=false){
 const s=financeState,request=++s.request,period=s.period,project=s.project,previous=s.report,offset=more?previous?.nextOffset:0;if(more&&offset==null)return;s.loading=true;s.error='';if(!more)s.report=null;drawFinance();
 try{const r=await call('financeReport',{period,project,offset});if(request!==s.request)return;if(!r?.ok||r.period!==period||r.project!==project)throw Error('Kết quả Thu chi không hợp lệ');s.report=more&&previous?{...r,items:[...previous.items,...r.items]}:r;s.loadedAt=Date.now()}
 catch(e){if(request===s.request){s.report=more?previous:null;s.error=e.message||String(e)}}
 finally{if(request===s.request){s.loading=false;drawFinance()}}
}


function editorProgressMarkup(x){
 const done=productionFinalApprovedClient(x)||x.stage==='published',handed=!!(x.editor_received_at||x.editor_handoff_at)||['edit','revision','review','ready','published'].includes(String(x.stage));if(!x.id||x.idea_approval!=='Duyệt'||!handed)return '';
 const n=done?100:Math.max(0,Math.min(90,Number(x.editor_progress)||0)),mine=String(state.user.id),editable=state.user.role!=='director'&&!done&&!!String(x.raw_url||'').trim()&&['edit','revision','review'].includes(String(x.stage))&&(x.editor_ids||[x.editor_id]).some(id=>String(id)===mine),actor=state.peopleNames?.[String(x.editor_progress_by)]||x.editor_progress_by||'';
 return '<div class="editor-progress"><div class="row"><b>Tiến độ Edit</b><span class="badge">'+n+'%</span></div><progress max="100" value="'+n+'" aria-label="Tiến độ Edit '+n+'%" style="width:100%;accent-color:#18e68d"></progress>'+(x.editor_progress_at?'<small>Cập nhật: '+esc(actor)+' · '+fmt(x.editor_progress_at)+'</small>':'')+(editable?'<details><summary>Cập nhật tiến độ</summary><form class="editorProgressForm" data-id="'+esc(x.id)+'"><label>Tiến độ hiện tại<select name="percent" required><option value="">Chọn tiến độ</option>'+Array.from({length:9},(_,i)=>{const p=(i+1)*10;return '<option value="'+p+'" '+(n===p?'selected':'')+'>'+p+'%</option>'}).join('')+'</select></label><small>Các Editor của video dùng chung tiến độ. Gửi hoàn thành để đạt 100%.</small><button type="submit">Lưu tiến độ</button></form></details>':'')+'</div>';
}
function bindEditorProgress(){$('screen').querySelectorAll('.editorProgressForm').forEach(f=>f.onsubmit=e=>{e.preventDefault();if(busy)return;const b=f.querySelector('button');b.disabled=true;b.textContent='Đang lưu…';run('setEditorProgress',f.dataset.id,Number(f.elements.percent.value)).finally(()=>{if(b.isConnected){b.disabled=false;b.textContent='Lưu tiến độ'}})})}
async function openProductionWork(id){if(busy)return;busy=true;msg('Đang mở task…');try{const r=await call('openProductionWorkTask',id);if(!r?.ok||!r.item)throw Error('Không mở được task');approvalFocus={...r,kind:'task'};Object.assign(state,{productionPeople:r.productionPeople,peopleNames:r.peopleNames,projects:r.projects});productionReady=true;window._operationalTarget=null;tab='production';render();msg('')}catch(e){msg(e.message||String(e),true)}finally{busy=false}}
function operationalWorkCard(x){return '<div class="item"><div class="row"><b>'+esc(x.title)+'</b><span class="badge wait">'+esc(x.status)+'</span></div><small>'+esc(x.assignee_name)+' · '+esc(x.detail)+'</small><small>Tạo lúc: '+fmt(x.created_at)+'</small><button type="button" data-open-operational="'+esc(x.record_id)+'" data-kind="'+esc(x.operational_kind)+'" data-point="'+esc(x.point||'')+'">Mở để xử lý</button></div>'}
function operationalTargetItems(kind,items){const t=window._operationalTarget;return t?.operational_kind===kind?items.filter(x=>String(x.id)===String(t.record_id)):items}
function operationalTargetBanner(){const t=window._operationalTarget,expected={leave:'leave',loan:'equipment',expense:'expenses',attendance:'fieldReview'};if(!t||tab!==expected[t.operational_kind])return;const screen=$('screen');if(screen.querySelector('#operationalBack'))return;const box=document.createElement('section');box.className='card';box.innerHTML='<h2>'+esc(t.title)+'</h2><p>Đang mở đúng phiếu từ Công việc.</p><button type="button" id="operationalBack" class="secondary">Quay lại Công việc</button>';screen.prepend(box);for(const id of ['leaveForm','loanForm','expenseForm','accountantForm'])$(id)?.closest?.('section')?.setAttribute('hidden','');$('operationalBack').onclick=()=>go('tasks');}
async function openOperationalTarget(kind,id,point){if(busy)return;busy=true;msg('Đang mở phiếu cần xử lý…');try{if(!coreReady)await loadCore();const r=await call('openOperationalWork',kind,id,point||'');if(!r?.ok||!r.item)throw Error('Không mở được phiếu');window._operationalTarget=r.entry;approvalFocus=null;state.hrApproverId=r.hrApproverId;state.accountantId=r.accountantId;state.peopleNames={...state.peopleNames,...r.peopleNames};const key={leave:'hrLeaveQueue',loan:'equipmentLoans',expense:'expenses'}[kind];if(key)state[key]=[r.item,...(state[key]||[]).filter(x=>String(x.id)!==String(id))];if(kind==='attendance')window._fieldReviewDate=r.entry.date;tab={leave:'leave',loan:'equipment',expense:'expenses',attendance:'fieldReview'}[kind];formDirty=false;render();window.scrollTo(0,0);msg('')}catch(e){msg(e.message||String(e),true);loadReviewQueue()}finally{busy=false}}

function finishOperationalWork(){window._operationalTarget=null;tab="tasks";state.reviewQueue=null;formDirty=false;render();loadReviewQueue();}

const expenseContentCache=new Map();
function bindExpenseProductionFields(form){
 const project=form.elements.project,select=form.elements.production_id,status=$('expenseContentStatus'),retry=$('expenseContentRetry'),submit=form.querySelector('button[type="submit"]');let version=0;
 const active=()=>form.isConnected&&tab==='expenses';const canSubmit=()=>{submit.disabled=form.dataset.contentLoading==='1'||!select.value};
 const draw=items=>{retry.hidden=false;retry.textContent='Làm mới nội dung';select.innerHTML='<option value="">'+(items.length?'Chọn nội dung sản xuất':'Dự án chưa có nội dung phù hợp')+'</option>'+items.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.title)+'</option>').join('');select.disabled=!items.length;status.textContent=items.length?'Có '+items.length+' nội dung. Bắt buộc chọn một nội dung để gửi phiếu.':'Chưa có nội dung sản xuất bạn được quyền xem trong dự án này. Hãy tạo nội dung hoặc kiểm tra phân công.';};
 const load=async(force=false)=>{const request=++version,key=String(project.value);select.value='';retry.hidden=true;form.dataset.contentLoading='0';status.setAttribute('aria-busy','false');if(!key){select.innerHTML='<option value="">Chọn dự án trước</option>';select.disabled=true;status.textContent='Chọn dự án để tải nội dung sản xuất.';canSubmit();return}
 const cached=expenseContentCache.get(key);if(!force&&cached&&Date.now()-cached.at<30000){draw(cached.items);canSubmit();return}
 form.dataset.contentLoading='1';select.disabled=true;select.innerHTML='<option value="">Đang tải nội dung…</option>';status.textContent='Đang tải nội dung sản xuất…';status.setAttribute('aria-busy','true');canSubmit();
 try{const r=await call('expenseProductionOptions',key);if(!active()||request!==version)return;if(!r?.ok||r.project!==key||!Array.isArray(r.items))throw Error('Máy chủ chưa trả danh sách nội dung hợp lệ');expenseContentCache.set(key,{at:Date.now(),items:r.items});draw(r.items)}catch(e){if(active()&&request===version){select.innerHTML='<option value="">Chưa tải được nội dung</option>';select.disabled=true;status.textContent=e.message||String(e);retry.textContent='Thử tải lại nội dung';retry.hidden=false}}finally{if(active()&&request===version){form.dataset.contentLoading='0';status.setAttribute('aria-busy','false');canSubmit()}}
 };
 project.onchange=()=>load();select.onchange=canSubmit;retry.onclick=()=>load(true);canSubmit();
}

function vjScriptMarkup(x){
 if(!x.id||x.idea_approval!=='Duyệt')return '';const handed=!!(x.editor_received_at||x.editor_handoff_at)||['edit','review','revision','ready','published'].includes(String(x.stage)),started=!!x.vj_script_started_at,waiting=['script','shoot'].includes(String(x.stage)),mine=state.user.role!=='director'&&(x.vj_ids||[x.vj_id]).some(id=>String(id)===String(state.user.id));if(!waiting&&!started)return '';
 const due=rawDeliveryDue(x),late=!!due&&!handed&&Date.parse(due)<Date.now(),actor=state.peopleNames?.[String(x.vj_script_started_by)]||x.vj_script_started_by||'';
 return '<div class="vj-script-timing"><div class="row"><b>'+(handed?'Đã bàn giao tư liệu':started?'Đang làm kịch bản':'Kịch bản / bàn giao tư liệu')+'</b>'+(late?'<span class="badge wait">Quá hạn</span>':'')+'</div>'+(started?'<small>Bắt đầu: '+fmt(x.vj_script_started_at)+' · '+esc(actor)+'</small><small'+(late?' style="color:#ff918b"':'')+'>Hạn bàn giao tư liệu: '+fmt(due)+' · 12 giờ từ lúc bắt đầu</small>':'<small>Chưa bắt đầu tính hạn. VJ bấm Đang làm kịch bản để bắt đầu 12 giờ bàn giao.</small>')+(!started&&waiting&&!handed&&mine?'<button type="button" data-vj-script-start="'+esc(x.id)+'">Đang làm kịch bản</button>':'')+'</div>';
}
function bindVJScript(){$('screen').querySelectorAll('[data-vj-script-start]').forEach(b=>b.onclick=()=>{if(busy)return;b.disabled=true;b.setAttribute('aria-busy','true');b.textContent='Đang bắt đầu…';run('startVJScript',b.dataset.vjScriptStart).finally(()=>{if(b.isConnected){b.disabled=false;b.removeAttribute('aria-busy');b.textContent='Đang làm kịch bản'}})})}

function expenseProductionMarkup(x){const id=String(x.production_id||'').trim(),fallback=x.production_link_state?null:(state.productionItems||[]).find(t=>String(t.id)===id),title=String(x.production_title||fallback?.title||''),kind=x.production_link_state||(!id?'unlinked':title?'linked':'missing');return '<small class="expense-production"><b>Nội dung sản xuất:</b> '+esc(title||(kind==='unlinked'?'Phiếu cũ chưa liên kết nội dung':'Không tìm thấy nội dung · '+id))+(kind==='deleted'?' · Nội dung đã xóa':'')+'</small>';}

