const hrEditPersonnelOnly=hrEdit;
hrEdit=function(p){
 hrEditPersonnelOnly(p);
 if(!p.employee_id||!(state.user.role==='director'||String(state.user.id)===String(state.hrApproverId||'')))return;
 $('screen').insertAdjacentHTML('beforeend','<section class="card"><h2>Đăng nhập web · '+esc(p.name)+'</h2><p>Telegram ID: <b>'+esc(p.telegram_id)+'</b>. Giữ nguyên ID và lịch sử của nhân viên.</p><form id="hrLoginForm"><label>Gmail / Email đăng nhập<input id="hrLoginEmail" name="email" type="email" required maxlength="254" autocomplete="off"></label><label>Mật khẩu mới<input id="hrLoginPassword" name="password" type="password" required minlength="6" maxlength="128" autocomplete="new-password" placeholder="Tối thiểu 6 ký tự"></label><p class="muted">Mật khẩu không hiện lại, không lưu trong Sheet hoặc nhật ký hồ sơ. Bấm nút dưới để cấp hoặc cập nhật đăng nhập.</p><button id="hrLoginSave">Lưu email và mật khẩu</button></form><p id="hrLoginStatus" class="muted">Đang kiểm tra tài khoản…</p></section>');
 const id=String(p.telegram_id),email=$('hrLoginEmail'),status=$('hrLoginStatus');
 fetch('/api/viral/hr/accounts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'profile-access',values:{telegram_id:id},initData:tg?.initData||''})}).then(async r=>{const d=await r.json();if(!r.ok)throw Error(d.error);if(email.isConnected){email.value=d.email||'';status.textContent=d.hasAccount?'Đã có đăng nhập web. Nhập mật khẩu mới nếu cần cập nhật.':'Chưa có đăng nhập web. Nhập email và mật khẩu để cấp.'}}).catch(e=>{if(status.isConnected)status.textContent=e.message||String(e)});
 $('hrLoginForm').onsubmit=async e=>{e.preventDefault();if(busy)return;if($('hrEditForm')?.dataset.edited)return msg('Hồ sơ có thay đổi chưa lưu. Lưu thông tin hồ sơ trước khi cấp đăng nhập.',true);busy=true;const button=$('hrLoginSave');button.disabled=true;msg('Đang lưu đăng nhập…');try{const values={telegram_id:id,email:email.value,password:$('hrLoginPassword').value},r=await fetch('/api/viral/hr/accounts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'profile-account',values,initData:tg?.initData||''})}),d=await r.json();if(!r.ok)throw Error(d.error);$('hrLoginPassword').value='';status.textContent=d.message;msg(d.message);formDirty=false;}catch(e){msg(e.message||String(e),true)}finally{busy=false;if(button.isConnected)button.disabled=false}};
};

